INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('CFO AI Leverage Report: AI Budgets, ROI and Finance Sign-Off', 'The Executive Community by Open Future Forum', 'Tech & Software', 'Enterprise AI is moving from experimentation into the finance office. Open Future Forum has released the **CFO AI Leverage Report, Edition', 'Enterprise AI is moving from experimentation into the finance office. Open Future Forum has released the **CFO AI Leverage Report, Edition 1**, introducing the **Enterprise AI Buying & Budget Index** and the **CFO AI Leverage Index**. The report examines how CFOs and senior finance leaders are evaluating AI budgets, buying authority, ROI, productivity, governance and the question now sitting at the center of enterprise AI adoption: **Can AI help companies grow output without growing headcount More info: https://www.meetup.com/silicon-valley-ai-executive-community-by-open-future-forum/events/316651445/', '2026-10-11T08:30:00-07:00', 'Fairfield by Marriott Inn & Suites New York Midtown Manhattan/Penn Station', '325 W 33rd St, New York, NY 10001', 'Manhattan', 'NY', '10001', 40.751880399645, -73.994640841404, 'The Executive Community by Open Future Forum', 1, false, '$3000', 'live', 'meetup', 'https://www.meetup.com/silicon-valley-ai-executive-community-by-open-future-forum/events/316651445/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
