INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('The Quantified Self: Gary Wolf on What AI Can Actually Tell You About Your Data', 'Startup Grind NYC', 'Women in Business', '🚨 **[CLICK HERE TO RSVP](https://www.startupgrind.com/e/my9dfp/)** 👈 This year, OpenAI started letting people connect their medical records', '🚨 **[CLICK HERE TO RSVP](https://www.startupgrind.com/e/my9dfp/)** 👈 This year, OpenAI started letting people connect their medical records and Apple Health data to ChatGPT. Since 2024, Americans can buy a continuous glucose monitor without a prescription. For most of the **[Quantified Self](http://quantifiedself.com/)** movement''s history, answering a question with your own data meant manual logs and spreadsheets. Today a sensor collects the data **and an AI model analyzes it on demand**. That More info: https://www.meetup.com/startup-grind-nyc/events/316669301/', '2026-10-15T17:00:00-04:00', 'Civic Hall', '124 E 14th St, New York, NY 10003, USA', 'New York', 'NY', '10003', 40.733737863973, -73.988393451312, 'Startup Grind NYC', 1, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/startup-grind-nyc/events/316669301/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
